using System;
using System.Text;
using System.Threading.Tasks;

class Node
{
    public Node Left, Right;
    public Node(Node l, Node r) { Left = l; Right = r; }
}

class Program
{
    static Node MakeTree(int depth)
    {
        if (depth == 0) return new Node(null, null);
        return new Node(MakeTree(depth - 1), MakeTree(depth - 1));
    }

    static int Check(Node node)
    {
        if (node.Left == null) return 1;
        return 1 + Check(node.Left) + Check(node.Right);
    }

    static void Main(string[] args)
    {
        int n = int.Parse(args[0]);
        int minDepth = 4;
        int maxDepth = Math.Max(minDepth + 2, n);
        int stretchDepth = maxDepth + 1;

        var sb = new StringBuilder();

        Node stretch = MakeTree(stretchDepth);
        sb.AppendFormat("stretch tree of depth {0}\t check: {1}\n", stretchDepth, Check(stretch));
        stretch = null;

        Node longLived = MakeTree(maxDepth);

        int groups = (maxDepth - minDepth) / 2 + 1;
        string[] results = new string[groups];

        Parallel.For(0, groups, gi =>
        {
            int depth = minDepth + gi * 2;
            int iterations = 1 << (maxDepth - depth + minDepth);
            int sum = 0;
            for (int i = 0; i < iterations; i++)
            {
                sum += Check(MakeTree(depth));
            }
            results[gi] = string.Format("{0}\t trees of depth {1}\t check: {2}", iterations, depth, sum);
        });

        for (int i = 0; i < groups; i++)
            sb.Append(results[i]).Append('\n');

        sb.AppendFormat("long lived tree of depth {0}\t check: {1}\n", maxDepth, Check(longLived));

        Console.Write(sb.ToString());
    }
}
