    static void WriteFrequencies(StringBuilder output, int k)
    {
        var counts = BuildCounts(k);
        int total = 0;
        foreach (var kv in counts) total += kv.Value;

        var list = new List<KeyValuePair<long, int>>(counts);
        list.Sort((a, b) =>
        {
            int cmp = b.Value.CompareTo(a.Value);
            if (cmp != 0) return cmp;
            return a.Key.CompareTo(b.Key);
        });

        foreach (var kv in list)
        {
            string kmer = DecodeKey(kv.Key, k);
            double pct = total > 0 ? (kv.Value * 100.0 / total) : 0.0;
            output.Append(kmer);
            output.Append(' ');
            output.Append(pct.ToString("F3", System.Globalization.CultureInfo.InvariantCulture));
            output.Append('\n');
        }
    }

    static Dictionary<long, int> BuildCounts(int k)
    {
        var dict = new Dictionary<long, int>();
        if (seqLen < k) return dict;
        long key = 0;
        long mask = (1L << (2 * k)) - 1;
        for (int i = 0; i < k - 1; i++)
        {
            key = (key << 2) | seq[i];
        }
        for (int i = k - 1; i < seqLen; i++)
        {
            key = ((key << 2) | seq[i]) & mask;
            if (dict.TryGetValue(key, out int v))
                dict[key] = v + 1;
            else
                dict[key] = 1;
        }
        return dict;
    }

    static string DecodeKey(long key, int k)
    {
        char[] buf = new char[k];
        for (int i = k - 1; i >= 0; i--)
        {
            buf[i] = letters[(int)(key & 3)];
            key >>= 2;
        }
        return new string(buf);
    }

    static long CountFragment(string frag)
    {
        int k = frag.Length;
        if (seqLen < k) return 0;
        long target = 0;
        for (int i = 0; i < k; i++)
        {
            byte code;
            switch (frag[i])
            {
                case 'A': code = 0; break;
                case 'C': code = 1; break;
                case 'G': code = 2; break;
                case 'T': code = 3; break;
                default: code = 0; break;
            }
            target = (target << 2) | code;
        }
        long mask = (k >= 32) ? -1L : ((1L << (2 * k)) - 1);
        long key = 0;
        long count = 0;
        for (int i = 0; i < k - 1; i++)
        {
            key = (key << 2) | seq[i];
        }
        for (int i = k - 1; i < seqLen; i++)
        {
            key = ((key << 2) | seq[i]) & mask;
            if (key == target) count++;
        }
        return count;
    }
